Ux39SmokeProbe::Ux39SmokeProbe(TaskWorkspace& workspace,QQuickWindow* window,QString screenshot):m_workspace(workspace),m_window(window),m_screenshot(std::move(screenshot)){m_wait.start();m_clock.start();}
QObject* Ux39SmokeProbe::find(QObject* root,const QString& name) const {
    QList<QObject*> pending{root};QSet<QObject*> seen;
    while(!pending.isEmpty()){
        auto* object=pending.takeLast();if(!object || seen.contains(object))continue;seen.insert(object);
        if(object->objectName()==name)return object;
        pending.append(object->children());
        if(auto* item=qobject_cast<QQuickItem*>(object))for(auto* child:item->childItems())pending.append(child);
        if(auto* window=qobject_cast<QQuickWindow*>(object))pending.append(window->contentItem());
    }
    return nullptr;
}
void Ux39SmokeProbe::click(QQuickItem* item,bool twice) {
    if(!item)return;
    auto* window=item->window();const auto at=item->mapToScene(QPointF(item->width()*0.75,item->height()*0.5));
    QList<QEvent::Type> events={QEvent::MouseMove,QEvent::MouseButtonPress,QEvent::MouseButtonRelease};
    if(twice)events.append({QEvent::MouseButtonPress,QEvent::MouseButtonDblClick,QEvent::MouseButtonRelease});
    for(const auto type:events){QMouseEvent event(type,at,window->mapToGlobal(at),type==QEvent::MouseMove?Qt::NoButton:Qt::LeftButton,type==QEvent::MouseButtonRelease?Qt::NoButton:Qt::LeftButton,Qt::NoModifier);event.setTimestamp(m_clock.elapsed()+m_sequence++);QCoreApplication::sendEvent(window,&event);}
}
void Ux39SmokeProbe::key(QQuickWindow* window,int code,Qt::KeyboardModifiers modifiers){for(const auto type:{QEvent::KeyPress,QEvent::KeyRelease}){QKeyEvent event(type,code,modifiers);QCoreApplication::sendEvent(window,&event);}}
void Ux39SmokeProbe::pointer(QEvent::Type type,const QPointF& at) {
    QMouseEvent event(type,at,m_window->mapToGlobal(at),type==QEvent::MouseMove?Qt::NoButton:Qt::LeftButton,type==QEvent::MouseButtonRelease?Qt::NoButton:Qt::LeftButton,Qt::NoModifier);
    event.setTimestamp(m_clock.elapsed()+m_sequence++);QCoreApplication::sendEvent(m_window,&event);
}
bool Ux39SmokeProbe::capture(const QString& suffix,QQuickWindow* window) const{return m_screenshot.isEmpty() || (window?window:m_window.data())->grabWindow().save(m_screenshot+".calendar-"+suffix+".png");}
